import 'fake-indexeddb/auto';
import Dexie from 'dexie';
import {it,expect,afterEach,vi} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {newId} from '../src/domain/model';
import {ScopedEditorStore,type EditorImage,type EditorWork} from '../src/sync/editorStore';
import {valueHash,type SyncAck} from '../src/sync/protocol';
import {threeWayMerge} from '../src/sync/merge';
const root='/tmp/shinariokanri-independent-rb09-73a279a/independent',stores:ScopedEditorStore[]=[];
afterEach(async()=>{vi.restoreAllMocks();for(const s of stores.splice(0))await s.delete();});
function proof(id:string,data:unknown){writeFileSync(`${root}/fixtures/${id}.json`,JSON.stringify(data,null,2)+'\n');}
function fixed(){const initial=JSON.parse(readFileSync(`${root}/fixed-fixtures/R9E00.json`,'utf8')).initial;return initial.base as EditorImage;}
async function image(revision='1',expiresAt:string|null=null){return {...fixed(),authorizationRevision:revision,authorizationExpiresAt:expiresAt};}
async function seed(expiresAt:string|null=null){const s=new ScopedEditorStore(newId());stores.push(s);const x=await image('1',expiresAt);await s.receive(x);return {s,x,id:x.documents[0].id};}
it('R9E04A authority1→withdrawal2→delayed1 and same2 expansion refuse; explicit regrant3 restores exactly current granted fields',async()=>{const f=await seed(),reduced=structuredClone(f.x);delete reduced.documents[0].fields.name;reduced.authorizationRevision='2';reduced.contentHash=await valueHash(reduced.documents);await f.s.receive(reduced);const before=await f.s.get(f.x.projectId);await expect(f.s.receive(f.x)).rejects.toMatchObject({code:'REVISION_CHANGED'});await expect(f.s.receive({...f.x,authorizationRevision:'2'})).rejects.toMatchObject({code:'REVISION_CHANGED'});expect(await f.s.get(f.x.projectId)).toEqual(before);await f.s.receive({...f.x,authorizationRevision:'3'});expect((await f.s.get(f.x.projectId))!.documents[0].fields.name).toBe(f.x.documents[0].fields.name);proof('R9E04A',{initial:f.x,reduced,before,after:await f.s.get(f.x.projectId)});});
it('R9E04B missing/unknown or expired authority stamps never create an active editor cache',async()=>{for(const input of [fixed(),{...fixed(),authorizationRevision:'unknown',authorizationExpiresAt:null},{...fixed(),authorizationRevision:'1',authorizationExpiresAt:new Date(Date.now()-1).toISOString()}]){const s=new ScopedEditorStore(newId());stores.push(s);await expect(s.receive(input)).rejects.toThrow();expect(await s.get(input.projectId)).toBeUndefined();}proof('R9E04B',{legacyMissingRefused:true,unknownRefused:true,expiredRefused:true});});
it('R9E04C original editorDBv1 unstamped base/local/prepared/ACK/post-conflicts migrate as exact recovered evidence and empty active documents; current authority alone resumes allowed input',async()=>{const file=JSON.parse(readFileSync(`${root}/fixed-fixtures/legacy-scoped-postconflict.json`,'utf8')),old=file.captured as EditorWork,account=old.prepared!.operation.scope.accountId,db=new Dexie('scenario-editor-account-'+encodeURIComponent(account));db.version(1).stores({works:'projectId'});await db.table('works').put(old);db.close();const s=new ScopedEditorStore(account);stores.push(s);const migrated=(await s.get(old.projectId))!;expect(migrated.documents).toEqual([]);expect(migrated.base.documents).toEqual([]);expect(migrated.recovered).toContainEqual(old);expect(migrated.prepared).toBeUndefined();expect(migrated.conflict).toBeUndefined();await expect(s.saveField(old.projectId,old.documents[0].id,'name','未知権限')).rejects.toMatchObject({code:'FORBIDDEN'});await expect(s.prepare(old.projectId)).rejects.toMatchObject({code:'FORBIDDEN'});const remote={...old.base,authorizationRevision:'1',authorizationExpiresAt:null};await s.receive(remote);const plan=await s.previewRecovery(old.projectId,0);await s.adoptRecovery(plan);const after=(await s.get(old.projectId))!;expect(after.recovered).toContainEqual(old);expect(after.acks).toEqual(old.acks);expect(after.prepared).toBeUndefined();expect(after.documents.map(d=>d.id)).toEqual(remote.documents.map(d=>d.id));proof('R9E04C',{old,migrated,plan,after});});
it('R9E05 expired conflict-resolution authorization rejects before updating local choices/confirmed base/prepared command',async()=>{const expires=Date.now()+60000,f=await seed(new Date(expires).toISOString());await f.s.saveField(f.x.projectId,f.id,'name','端末案');const operation=(await f.s.prepare(f.x.projectId))!,base=operation.targets[0].base!,remote=structuredClone(base);remote.fields.name='遠隔案';remote.revision='2';const ack:SyncAck={schemaVersion:1,operationId:operation.operationId,scope:operation.scope,operationHash:await valueHash(operation),status:'conflict',serverRevision:'2',authorizationRevision:'1',authorizationExpiresAt:new Date(expires).toISOString(),documents:[remote],confirmedDocuments:f.x.documents.map(d=>d.id===f.id?remote:d),conflicts:[(()=>{const result=threeWayMerge(base,operation.targets[0].local,remote);if(result.status!=='conflict')throw Error('REVIEW_CONFLICT_NOT_CONSTRUCTED');return result.conflict;})()]};await f.s.acknowledge(ack);const before=(await f.s.get(f.x.projectId))!;vi.spyOn(Date,'now').mockReturnValue(expires+1);let error;try{await f.s.resolve(f.x.projectId,{[f.id]:{strategy:'server'}},before.revision);}catch(e){error=e;}const after=await f.s.get(f.x.projectId);proof('R9E05',{before,after,error:String(error),deadline:new Date(expires).toISOString()});expect(error).toMatchObject({code:'FORBIDDEN'});expect(after).toEqual(before);});
it('R9E06 a recovery approval created before authorization expiry cannot adopt active editor values after expiry',async()=>{const expires=Date.now()+60000,f=await seed(new Date(expires).toISOString()),historical=(await f.s.get(f.x.projectId))!;historical.documents[0].fields.name='旧記録の入力';await f.s.retainRecovery(historical);const plan=await f.s.previewRecovery(f.x.projectId,0),before=await f.s.get(f.x.projectId);vi.spyOn(Date,'now').mockReturnValue(expires+1);let error;try{await f.s.adoptRecovery(plan);}catch(e){error=e;}const after=await f.s.get(f.x.projectId);proof('R9E06',{before,after,plan,error:String(error)});expect(error).toMatchObject({code:'FORBIDDEN'});expect(after).toEqual(before);});
